import os, re, subprocess, shutil
from pathlib import Path

src_dir = Path('all')
dst_dirs = {
    'LLM': Path('LLM'),
    'trapped_ion_and_qc': Path('trapped_ion_and_qc'),
    'black_hole': Path('black_hole'),
    'DNA': Path('DNA'),
